    /*
     * Add to the CompetencyRatings
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	PerformanceReview
     */
    public PerformanceReview addToCompetencyRatings( UUID parentId, CompetencyRating addTo ) {
	    LOGGER.info("handling AssignCompetencyRatingsToPerformanceReviewEvent - " );
	    
	    PerformanceReview parentEntity = repository.findById(parentId).get();
	    CompetencyRating child = registry.project( CompetencyRating.class, addTo.getCompetencyRatingId());
	    
	    parentEntity.getCompetencyRatings().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

